# Equivalent, reviewed by hand and kept out of the run (no input can tell them apart from the source):
EQUIVALENT={'P59_bind_empty_order':'0<=len(owner_order_text): the empty text already fails the ASCII grammar [ -~]+',
            'A21_argument_count_unbounded':'the largest argv of the compiled table has 41 middle words (acquire) < MAX_ARGUMENTS 64',
            'A25_validate_skips_argv':'every value the builder reads is validated before it by validate_plan; kept as a guard',
            'E64_success_with_an_uncertain_effect':'a safety net: every path that reaches COMPLETE has settled each effect (the tests of each path show it)',
            'E10_removal_not_started_not_stopped':'a removal that never started also never returned: the next line stops with the same code and phase',
            'E19_plan_risk_everywhere':'plan[bind] is null for every step but bind (validate_plan), so the two expressions are equal',
            'E25_timeout_minimum_not_checked':'the precheck requires 155 s to run_not_after and a run lasts at most 60 s: the timeout at create is at least 90 s',
            'E57_deferred_removal_settled_twice':'no path reads a removal back twice (each stop returns after its one readback); kept as a guard',
            'K66_runtime_source_root_device':'walk_pinned compares the device with the signed rows, which validate_plan has already required equal to days/\'s',
            'K69_mount_source_owner_any':'owner, group and mode of every bind source are refused earlier (signed rows, DAY_DIRECTORY_NOT_PRIVATE, DAY_LAYOUT_INVALID, EMITTER_SECRET_NOT_PRIVATE); defence in depth',
            'K19_marker_not_required':'the receipt substituted for the marker never passes the marker checks: the same refusal'}
MUTANTS=[row for row in M if row[0] not in EQUIVALENT]
